# Default per-servo current thresholds (mA). These match the collect-pose
# experiment so the demo can never be more aggressive than data collection.
DEFAULT_CURRENT_WARNING_MA = 800
DEFAULT_SUSTAINED_OVERCURRENT_MA = 1200
DEFAULT_SUSTAINED_OVERCURRENT_SAMPLES = 3

# Default tick caps. These are intentionally tighter than the collect-pose
# defaults because this is a demo: the operator should choose to raise
# them rather than have aggressive defaults baked in.
DEFAULT_MAX_TICK_DELTA_FROM_STARTUP = 200
DEFAULT_HARD_MAX_TICK_DELTA_FROM_STARTUP = 600
DEFAULT_MAX_STEP_TICKS_PER_UPDATE = 25


def _optional_non_negative_int(payload: dict[str, Any], key: str) -> int | None:
    """Parse an optional non-negative int from a config payload.

    Returns None when the key is absent or the value is None / empty string
    (so the bus default is preserved); otherwise coerces to a clamped
    non-negative int. Used by the slow motion demo's profile_velocity /
    profile_acceleration knobs.
    """
    if key not in payload:
        return None
    value = payload.get(key)
    if value is None or value == "":
        return None
    try:
        coerced = int(value)
    except (TypeError, ValueError):
        return None
    return max(0, coerced)


@dataclass
class TwoSegmentSlowMotionDemoConfig:
    """Operator-facing config for the slow motion demo."""

    pattern: str = PATTERN_FIGURE8
    amplitude_cm: float = DEFAULT_AMPLITUDE_CM
    cycle_duration_s: float = DEFAULT_CYCLE_DURATION_S
    cycles: int = DEFAULT_CYCLES
    update_rate_hz: float = DEFAULT_UPDATE_RATE_HZ
    ramp_in_s: float = DEFAULT_RAMP_S
    ramp_out_s: float = DEFAULT_RAMP_S
    hold_at_start_s: float = DEFAULT_HOLD_S
    hold_at_end_s: float = DEFAULT_HOLD_S
    coupling: str = COUPLING_PHASE_SHIFTED
    top_scale: float = 0.5
    phase_offset_deg: float = 90.0
    lissajous_a: float = 1.0
    lissajous_b: float = 2.0
    lissajous_phase_deg: float = 0.0
    raster_ratio: float = 3.0
    random_seed: int = 0

    # Safety caps
    max_tick_delta_from_startup: int = DEFAULT_MAX_TICK_DELTA_FROM_STARTUP
    hard_max_tick_delta_from_startup: int = DEFAULT_HARD_MAX_TICK_DELTA_FROM_STARTUP
    max_step_ticks_per_update: int = DEFAULT_MAX_STEP_TICKS_PER_UPDATE
    current_warning_ma: int = DEFAULT_CURRENT_WARNING_MA
    sustained_overcurrent_ma: int = DEFAULT_SUSTAINED_OVERCURRENT_MA
    sustained_overcurrent_sample_count: int = DEFAULT_SUSTAINED_OVERCURRENT_SAMPLES
    top_segment_tendon_routing_compensation: bool = True
    return_to_neutral_at_end: bool = True

    # Motor speed envelope. Pushed to all 8 servos at the start of the run
    # and restored on finalize. ``None`` leaves the bus-configured default
    # in place (no profile write). Lower values → slower, smoother motion
    # between successive goal positions — useful for slide-video recordings
    # where you want the demo to look like a fluid drift rather than a
    # series of sharp steps. XC330 units:
    #   profile_velocity: 1 unit = 0.229 rpm; 0 = "as fast as possible".
    #   profile_acceleration: 1 unit ≈ 214.577 rev/min²; 0 = step input.
    # Reasonable starting points for the demo are ~30–80 for velocity and
    # ~10–30 for acceleration. ``None`` skips the write entirely so an
    # operator who only wants to use the existing bus defaults is not
    # forced to think about these.
    profile_velocity: int | None = None
    profile_acceleration: int | None = None

    # Sci-fi waypoint relay knobs (only consumed when ``pattern`` is
    # ``sci_fi_waypoint_relay``). All have sensible defaults that match
    # the 20-second "Sci-Fi Spine" preset. The relay-specific fields do
    # not affect any other pattern — operators using figure8, cinematic
    # drift, etc. can ignore them entirely.
    video_duration_s: float = 20.0
    waypoint_count: int = 9
    early_switch_fraction: float = 0.72
    waypoint_source: str = "preset_weird"  # or "seeded_maximin"
    relay_seed: int = 0
    auto_select_seed: bool = True
    min_waypoint_separation_norm: float = 0.40
    max_waypoint_separation_norm: float = 2.20
    # For sci_fi_waypoint_relay this is the dense blend sample rate AND the
    # bus write rate (the relay streams an interpolated path, not one write
    # per waypoint). 15 Hz is smooth and well under the ~30-50 Hz 8-servo
    # sync-write ceiling.
    command_rate_hz: float = 15.0

    # Mode + provenance
    dry_run: bool = True  # default ON: demo is meant to be previewed first
    allow_servo_only_test_run: bool = False
    tracker_overlay_enabled: bool = False
    run_label: str = ""

    @classmethod
    def from_dict(cls, payload: dict[str, Any] | None) -> "TwoSegmentSlowMotionDemoConfig":
        payload = dict(payload or {})
        amplitude_raw = payload.get("amplitude_cm", DEFAULT_AMPLITUDE_CM)
        try:
            amplitude = float(amplitude_raw)
        except (TypeError, ValueError):
            amplitude = DEFAULT_AMPLITUDE_CM
        # Snap to nearest preset only if the requested value is essentially
        # equal to one — never silently downscale.
        amplitude_cap = max(AMPLITUDE_PRESETS_CM)
        if amplitude > amplitude_cap + 1e-9:
            raise ValueError(
                f"amplitude_cm={amplitude} exceeds the conservative demo cap "
                f"({amplitude_cap} cm). Raise the cap deliberately if you really need more."
            )
        pattern = str(payload.get("pattern", PATTERN_FIGURE8) or PATTERN_FIGURE8).strip().lower()
        if pattern not in SUPPORTED_PATTERNS:
            raise ValueError(f"Unsupported pattern {pattern!r}; choose from {SUPPORTED_PATTERNS}.")
        coupling = str(payload.get("coupling", COUPLING_PHASE_SHIFTED) or COUPLING_PHASE_SHIFTED).strip().lower()
        if coupling not in SUPPORTED_COUPLINGS:
            raise ValueError(f"Unsupported coupling {coupling!r}; choose from {SUPPORTED_COUPLINGS}.")
        hard_cap = max(1, int(payload.get("hard_max_tick_delta_from_startup", DEFAULT_HARD_MAX_TICK_DELTA_FROM_STARTUP)))
        soft_cap = max(0, int(payload.get("max_tick_delta_from_startup", DEFAULT_MAX_TICK_DELTA_FROM_STARTUP)))
        if soft_cap > hard_cap:
            raise ValueError(
                f"max_tick_delta_from_startup={soft_cap} exceeds hard cap {hard_cap}; "
                "raise the hard cap deliberately if needed."
            )
        return cls(
            pattern=pattern,
            amplitude_cm=max(0.0, amplitude),
            cycle_duration_s=max(1.0, float(payload.get("cycle_duration_s", DEFAULT_CYCLE_DURATION_S))),
            cycles=max(1, int(payload.get("cycles", DEFAULT_CYCLES))),
            update_rate_hz=max(0.5, float(payload.get("update_rate_hz", DEFAULT_UPDATE_RATE_HZ))),
            ramp_in_s=max(0.0, float(payload.get("ramp_in_s", DEFAULT_RAMP_S))),
            ramp_out_s=max(0.0, float(payload.get("ramp_out_s", DEFAULT_RAMP_S))),
            hold_at_start_s=max(0.0, float(payload.get("hold_at_start_s", DEFAULT_HOLD_S))),
            hold_at_end_s=max(0.0, float(payload.get("hold_at_end_s", DEFAULT_HOLD_S))),
            coupling=coupling,
            top_scale=max(0.0, float(payload.get("top_scale", 0.5))),
            phase_offset_deg=float(payload.get("phase_offset_deg", 90.0)),
            lissajous_a=max(0.1, float(payload.get("lissajous_a", 1.0))),
            lissajous_b=max(0.1, float(payload.get("lissajous_b", 2.0))),
            lissajous_phase_deg=float(payload.get("lissajous_phase_deg", 0.0)),
            raster_ratio=max(1.0, float(payload.get("raster_ratio", 3.0))),
            random_seed=int(payload.get("random_seed", 0)),
            max_tick_delta_from_startup=soft_cap,
            hard_max_tick_delta_from_startup=hard_cap,
            max_step_ticks_per_update=max(1, int(payload.get("max_step_ticks_per_update", DEFAULT_MAX_STEP_TICKS_PER_UPDATE))),
            current_warning_ma=max(0, int(payload.get("current_warning_ma", DEFAULT_CURRENT_WARNING_MA))),
            sustained_overcurrent_ma=max(0, int(payload.get("sustained_overcurrent_ma", DEFAULT_SUSTAINED_OVERCURRENT_MA))),
            sustained_overcurrent_sample_count=max(1, int(payload.get("sustained_overcurrent_sample_count", DEFAULT_SUSTAINED_OVERCURRENT_SAMPLES))),
            top_segment_tendon_routing_compensation=bool(payload.get("top_segment_tendon_routing_compensation", True)),
            return_to_neutral_at_end=bool(payload.get("return_to_neutral_at_end", True)),
            profile_velocity=_optional_non_negative_int(payload, "profile_velocity"),
            profile_acceleration=_optional_non_negative_int(payload, "profile_acceleration"),
            video_duration_s=max(1.0, float(payload.get("video_duration_s", 20.0))),
            waypoint_count=max(2, int(payload.get("waypoint_count", 9))),
            early_switch_fraction=max(
                0.01,
                min(1.0, float(payload.get("early_switch_fraction", 0.72))),
            ),
            waypoint_source=str(payload.get("waypoint_source", "preset_weird") or "preset_weird").strip().lower(),
            relay_seed=int(payload.get("relay_seed", payload.get("seed", 0)) or 0),
            auto_select_seed=bool(payload.get("auto_select_seed", True)),
            min_waypoint_separation_norm=max(
                0.0, float(payload.get("min_waypoint_separation_norm", 0.40)),
            ),
            max_waypoint_separation_norm=max(
                0.0, float(payload.get("max_waypoint_separation_norm", 2.20)),
            ),
            command_rate_hz=max(0.5, float(payload.get("command_rate_hz", 15.0))),
            dry_run=bool(payload.get("dry_run", True)),
            allow_servo_only_test_run=bool(payload.get("allow_servo_only_test_run", False)),
            tracker_overlay_enabled=bool(payload.get("tracker_overlay_enabled", False)),
            run_label=str(payload.get("run_label", "") or ""),
        )

    def pattern_request(self) -> PatternRequest:
        """Return the pattern generator request for this config."""
        return PatternRequest(
            pattern=str(self.pattern),
            amplitude_cm=float(self.amplitude_cm),
            cycle_duration_s=float(self.cycle_duration_s),
            cycles=int(self.cycles),
            update_rate_hz=float(self.update_rate_hz),
            ramp_in_s=float(self.ramp_in_s),
            ramp_out_s=float(self.ramp_out_s),
            hold_at_start_s=float(self.hold_at_start_s),
            hold_at_end_s=float(self.hold_at_end_s),
            coupling=str(self.coupling),
            top_scale=float(self.top_scale),
            phase_offset_deg=float(self.phase_offset_deg),
            lissajous_a=float(self.lissajous_a),
            lissajous_b=float(self.lissajous_b),
            lissajous_phase_deg=float(self.lissajous_phase_deg),
            raster_ratio=float(self.raster_ratio),
            seed=int(self.random_seed),
        )


