@dataclass
class DemoTraceRow:
    """One trace row written per trajectory tick."""

    sample_index: int
    elapsed_s: float
    phase_label: str
    bottom_x_cm: float
    bottom_y_cm: float
    top_x_cm: float
    top_y_cm: float
    intended_flat_cm: list[float]
    servo_flat_cm: list[float]
    goal_ticks_by_servo: dict[int, int]
    present_ticks_by_servo: dict[int, int | None]
    max_current_ma: int | None
    command_sent: bool
    skip_reason: str | None
    safety_state: str

    def to_dict(self) -> dict[str, Any]:
        return {
            "sample_index": int(self.sample_index),
            "elapsed_s": float(self.elapsed_s),
            "phase_label": str(self.phase_label),
            "bottom_x_cm": float(self.bottom_x_cm),
            "bottom_y_cm": float(self.bottom_y_cm),
            "top_x_cm": float(self.top_x_cm),
            "top_y_cm": float(self.top_y_cm),
            "intended_flat_cm": [float(v) for v in self.intended_flat_cm],
            "servo_flat_cm": [float(v) for v in self.servo_flat_cm],
            "goal_ticks_by_servo": {str(k): int(v) for k, v in sorted(self.goal_ticks_by_servo.items())},
            "present_ticks_by_servo": {str(k): (None if v is None else int(v)) for k, v in sorted(self.present_ticks_by_servo.items())},
            "max_current_ma": None if self.max_current_ma is None else int(self.max_current_ma),
            "command_sent": bool(self.command_sent),
            "skip_reason": None if self.skip_reason is None else str(self.skip_reason),
            "safety_state": str(self.safety_state),
        }


def build_two_segment_command_for_point(
    point: TwoSegmentPatternPoint,
    *,
    bottom_segment_key: str,
) -> TwoSegmentCommand:
    """Map a generator point's bottom/top tendon vectors onto segment_a/b.

    The generator output is segment-indexed in *physical role* terms
    (bottom 4 first, top 4 second). The canonical command structure is
    indexed by ``segment_a`` / ``segment_b``, where which letter is bottom
    depends on the operating context's ``bottom_segment_key``. This helper
    is the single point where that mapping happens.
    """
    bottom_tendon = tuple(float(v) for v in point.bottom_tendon_cm)
    top_tendon = tuple(float(v) for v in point.top_tendon_cm)
    key = str(bottom_segment_key or "").strip().lower()
    if key == SEGMENT_A:
        return TwoSegmentCommand(segment_a=bottom_tendon, segment_b=top_tendon)
    if key == SEGMENT_B:
        return TwoSegmentCommand(segment_a=top_tendon, segment_b=bottom_tendon)
    raise ValueError(
        f"bottom_segment_key must be 'segment_a' or 'segment_b'; got {bottom_segment_key!r}."
    )


def _max_step_violation(
    *,
    goals_by_servo: dict[int, int],
    previous_goals_by_servo: dict[int, int],
    max_step_ticks: int,
) -> tuple[bool, int, int | None]:
    """Return (violation, max_step_observed, offending_servo_id)."""
    largest = 0
    offender: int | None = None
    for servo_id, goal in goals_by_servo.items():
        previous = int(previous_goals_by_servo.get(int(servo_id), int(goal)))
        delta = abs(int(goal) - previous)
        if delta > largest:
            largest = delta
            offender = int(servo_id)
    return largest > int(max_step_ticks), int(largest), offender


def _telemetry_max_current_ma(telemetry_by_servo: dict[int, Any]) -> int | None:
    """Return the largest reported ``current_ma`` across the given telemetry."""
    largest: int | None = None
    for item in telemetry_by_servo.values():
        if item is None:
            continue
        value = getattr(item, "current_ma", None)
        if value is None:
            continue
        try:
            value_int = int(value)
        except (TypeError, ValueError):
            continue
        if largest is None or value_int > largest:
            largest = value_int
    return largest


