class TwoSegmentSlowMotionDemoExperiment(BaseExperiment):
    """Open-loop slow command-pattern demo for the two-segment stacked robot."""

    name = "two_segment_slow_motion_demo"
    description = (
        "Presentation-only demo: drives the dual-segment robot through a slow, smooth, "
        "bounded command-space pattern (figure-8/circle/sweep/clover). Not data collection, "
        "not closed-loop, not model validation. Stamps demo_only / not_for_model_training "
        "flags on every artifact."
    )
    hardware_requirements = ExperimentHardwareRequirements(
        tracking_required=False,
        servo_required=True,
        registration_required=False,
        mock_compatible=True,
    )

    def __init__(self, config: TwoSegmentSlowMotionDemoConfig) -> None:
        super().__init__(config=config)
        self._trajectory: list[TwoSegmentPatternPoint] = []
        self._startup_ticks_by_servo: dict[int, int] = {}
        self._startup_provenance: dict[str, Any] = {}
        self._trace: list[DemoTraceRow] = []
        self._previous_goals_by_servo: dict[int, int] = {}
        self._consecutive_overcurrent_cycles = 0
        self._stop_reason: str = "not_started"
        self._max_current_observed_ma: int | None = None
        self._safety_halted = False
        # Sci-fi relay state. Populated by setup() when pattern is
        # ``sci_fi_waypoint_relay``; otherwise stays empty.
        self._relay_waypoints: list[Any] = []
        self._relay_schedule: list[Any] = []
        self._resolved_relay_seed: int = 0
        self._relay_advisory: Any = None
        # Profile restore success. ``None`` until the demo touches profile
        # settings; ``True`` if every restore write succeeded; ``False``
        # with a reason string if any restore failed (e.g. bus drop).
        self._profile_restore_success: bool | None = None
        self._profile_restore_failure_reason: str | None = None

    @classmethod
    def from_dict(cls, payload: dict[str, Any] | None = None) -> "TwoSegmentSlowMotionDemoExperiment":
        return cls(config=TwoSegmentSlowMotionDemoConfig.from_dict(payload))

    # --- setup / precheck --------------------------------------------------

    def setup(self, session: ExperimentSession) -> None:
        # Generate the trajectory up front so a hardware failure later in the
        # run still has the planned trajectory recorded in the bundle.
        if str(self.config.pattern or "").strip().lower() == "sci_fi_waypoint_relay":
            # Route through the dedicated relay builder so we get the
            # waypoint list + schedule + advisory alongside the sparse
            # trajectory points. The hold_at_start / hold_at_end values
            # from the operator's config are honored.
            from continuum_robot.demo.sci_fi_waypoint_relay import (
                SciFiRelayConfig,
                build_relay_trajectory,
                speed_advisory,
            )
            relay_cfg = SciFiRelayConfig(
                video_duration_s=float(self.config.video_duration_s),
                waypoint_count=int(self.config.waypoint_count),
                amplitude_cm=float(self.config.amplitude_cm),
                early_switch_fraction=float(self.config.early_switch_fraction),
                waypoint_source=str(self.config.waypoint_source),
                seed=int(self.config.relay_seed),
                auto_select_seed=bool(self.config.auto_select_seed),
                min_waypoint_separation_norm=float(self.config.min_waypoint_separation_norm),
                max_waypoint_separation_norm=float(self.config.max_waypoint_separation_norm),
                profile_velocity=int(self.config.profile_velocity or 0),
                profile_acceleration=int(self.config.profile_acceleration or 0),
                command_rate_hz=float(self.config.command_rate_hz),
            )
            (
                self._trajectory,
                self._relay_waypoints,
                self._relay_schedule,
                self._resolved_relay_seed,
            ) = build_relay_trajectory(
                relay_cfg,
                hold_at_start_s=float(self.config.hold_at_start_s),
                hold_at_end_s=float(self.config.hold_at_end_s),
            )
            self._relay_advisory = speed_advisory(relay_cfg)
        else:
            self._trajectory = generate_pattern_trajectory(self.config.pattern_request())
        context = getattr(getattr(session.context, "settings", None), "robot", None)
        expected_ids = [1, 2, 3, 4, 5, 6, 7, 8]
        if context is not None and hasattr(context, "operating_context"):
            try:
                op_context = context.operating_context()
                expected_ids = [int(v) for v in op_context.expected_servo_ids] or expected_ids
            except Exception:
                expected_ids = [1, 2, 3, 4, 5, 6, 7, 8]
        # Size the per-servo tick caps to the chosen amplitude so a live relay
        # run clears precheck on the first try. The waypoints are bounded to
        # +/-amplitude, but the top-tendon routing compensation can almost
        # double a top servo's displacement, so the conservative default soft
        # cap (200 ticks) is far too low for even a 0.35 cm relay. We only ever
        # RAISE the caps (never override a deliberately higher operator value)
        # and the budget is derived deterministically from the amplitude.
        if str(self.config.pattern or "").strip().lower() == "sci_fi_waypoint_relay":
            spool_cm = float(getattr(context, "spool_diameter_cm", 2.0) or 2.0)
            ticks_per_rev = int(getattr(context, "ticks_per_revolution", 4096) or 4096)
            budget = int(
                tick_budget_for_segment_amplitude_cm(
                    float(self.config.amplitude_cm),
                    spool_diameter_cm=spool_cm,
                    ticks_per_rev=ticks_per_rev,
                )
            )
            self.config.max_tick_delta_from_startup = max(
                int(self.config.max_tick_delta_from_startup), budget
            )
            self.config.hard_max_tick_delta_from_startup = max(
                int(self.config.hard_max_tick_delta_from_startup),
                int(self.config.max_tick_delta_from_startup),
            )
            # The dense blend moves in small smooth steps; let the per-step
            # guard reach the same budget so the relay never stutters by
            # skipping a write mid-flow. The soft/hard caps still bound the
            # absolute displacement.
            self.config.max_step_ticks_per_update = max(
                int(self.config.max_step_ticks_per_update), budget
            )
        if not self.config.dry_run and session.context.servo_service is not None:
            self._startup_ticks_by_servo, self._startup_provenance = _resolve_startup_ticks(
                session=session,
                config=_StartupResolveAdapter(self.config),
                expected_ids=expected_ids,
            )
        else:
            # Dry-run uses a synthetic neutral. The trace is still useful for
            # checking the trajectory shape, and the bundle records that this
            # was a dry-run so it cannot accidentally be promoted to thesis
            # evidence.
            self._startup_ticks_by_servo = {int(servo_id): 2048 for servo_id in expected_ids}
            self._startup_provenance = {
                "source": "dry_run_synthetic_neutral",
                "message": "Dry-run: startup ticks defaulted to 2048; bundle is not_thesis_evidence.",
                "accepted_all_8_startup": False,
            }
        session.set_metric("planned_sample_count", int(len(self._trajectory)))
        session.set_metric(
            "demo_metadata",
            {
                "demo_only": True,
                "valid_for_model_training": False,
                "valid_for_thesis_repeatability": False,
                "closed_loop_control": False,
                "motion_pattern_demo": True,
                "pattern": self.config.pattern,
                "amplitude_cm": float(self.config.amplitude_cm),
                "cycle_duration_s": float(self.config.cycle_duration_s),
                "cycles": int(self.config.cycles),
                "update_rate_hz": float(self.config.update_rate_hz),
                "coupling": self.config.coupling,
                "ramp_in_s": float(self.config.ramp_in_s),
                "ramp_out_s": float(self.config.ramp_out_s),
                "dry_run": bool(self.config.dry_run),
                "tracker_overlay_enabled": bool(self.config.tracker_overlay_enabled),
            },
        )
        session.set_metric("startup_reference", dict(self._startup_provenance))

    def precheck(self, session: ExperimentSession) -> None:
        if self.config.dry_run:
            # In dry-run we still validate the trajectory and the resolved
            # startup ticks; we just don't enforce dual_segment mode etc.
            if not self._trajectory:
                raise RuntimeError("Trajectory is empty; nothing to demo.")
            return
        context_provider = getattr(getattr(session.context, "settings", None), "robot", None)
        if context_provider is None:
            raise RuntimeError("Robot settings unavailable; cannot validate dual_segment mode.")
        context = context_provider.operating_context()
        if context.operating_mode != "dual_segment":
            raise RuntimeError(BLOCK_MESSAGE_MODE)
        assembly_issues = list(getattr(context, "physical_assembly_issues", []) or [])
        if assembly_issues:
            raise RuntimeError(
                "Two-segment slow motion demo requires a valid bottom/top physical assembly. "
                f"Issues: {'; '.join(assembly_issues)}"
            )
        if [int(v) for v in context.expected_servo_ids] != [1, 2, 3, 4, 5, 6, 7, 8]:
            raise RuntimeError(
                "Two-segment slow motion demo requires expected servo IDs [1..8]; "
                f"got {list(context.expected_servo_ids)}."
            )
        if session.context.servo_service is None or not session.context.servo_service.is_connected:
            raise RuntimeError("Two-segment slow motion demo requires a connected ServoService.")
        if not bool(self._startup_provenance.get("accepted_all_8_startup")):
            raise RuntimeError(BLOCK_MESSAGE_STARTUP)
        # Build all goal ticks for every trajectory point and check against
        # the configured soft cap. This is a static check against the
        # planned trajectory, before any bus write happens.
        violations = self._trajectory_safety_violations(session=session, context=context)
        if violations:
            raise RuntimeError(
                "Two-segment slow motion trajectory exceeds the configured tick cap: "
                + "; ".join(violations[:5])
            )
        session.set_stage("precheck", "passed", "dual_segment slow motion demo precheck passed.")

    def _trajectory_safety_violations(self, *, session: ExperimentSession, context) -> list[str]:
        violations: list[str] = []
        commanded_ids = [int(value) for value in context.commanded_servo_ids]
        startup_ticks = [int(self._startup_ticks_by_servo[int(servo_id)]) for servo_id in commanded_ids]
        bottom_segment_key = str(getattr(context, "bottom_segment_key", "") or "")
        mapper = session.context.servo_service.mapper
        for point in self._trajectory:
            command = build_two_segment_command_for_point(
                point, bottom_segment_key=bottom_segment_key
            )
            intended_flat = command.to_flat(context=context)
            if self.config.top_segment_tendon_routing_compensation:
                servo_flat, _info = _apply_top_routing_compensation(intended_flat, context=context)
            else:
                servo_flat = list(intended_flat)
            goals = mapper.to_goal_positions(servo_flat, startup_ticks)
            for servo_id, startup, goal in zip(commanded_ids, startup_ticks, goals):
                delta = abs(int(goal) - int(startup))
                if delta > int(self.config.max_tick_delta_from_startup):
                    violations.append(
                        f"sample {point.sample_index}: servo {servo_id} delta {delta} > "
                        f"{int(self.config.max_tick_delta_from_startup)}"
                    )
                if delta > int(self.config.hard_max_tick_delta_from_startup):
                    violations.append(
                        f"sample {point.sample_index}: servo {servo_id} delta {delta} > "
                        f"HARD CAP {int(self.config.hard_max_tick_delta_from_startup)}"
                    )
        return violations

    # --- execute -----------------------------------------------------------

    def execute(self, session: ExperimentSession) -> None:
        context_provider = getattr(getattr(session.context, "settings", None), "robot", None)
        if context_provider is None and self.config.dry_run:
            # In dry-run with a stub session we still want a useful trace,
            # so synthesize a minimal context-like object using SEGMENT_A as
            # bottom and IDs [1..8] in canonical order. The trace records this
            # is a dry-run with no servo writes.
            context = _DryRunContext()
        else:
            assert context_provider is not None
            context = context_provider.operating_context()
        commanded_ids = [int(v) for v in context.commanded_servo_ids]
        startup_ticks = [int(self._startup_ticks_by_servo[int(servo_id)]) for servo_id in commanded_ids]
        bottom_segment_key = str(getattr(context, "bottom_segment_key", "") or "")
        sleep_fn = session.context.sleep_fn

        servo_service = session.context.servo_service
        mapper = (
            servo_service.mapper
            if servo_service is not None and getattr(servo_service, "mapper", None) is not None
            else _DryRunMapper()
        )

        # Acquire exclusive servo-bus ownership for the duration of the demo so
        # that background telemetry pollers and other concurrent code paths do
        # not race the demo's writes (every other live-motion experiment does
        # this; the slow motion demo was missing it, which produced spurious
        # "bus is owned by active … background refresh is paused" errors
        # mid-run that the operator perceived as "experiment already running").
        # Dry-run skips the lock because there is no live bus and no
        # servo_service to lock against on a stub session.
        live_bus_lock = (
            not self.config.dry_run
            and servo_service is not None
            and getattr(servo_service, "is_connected", False)
        )
        bus_owner_cm = None
        if live_bus_lock:
            bus_owner_cm = servo_service.exclusive_bus_operation(
                owner="two_segment_slow_motion_demo",
                reason=f"slow motion {self.config.pattern} pattern, {self.config.cycles} cycle(s)",
            )
            bus_owner_cm.__enter__()

        # Push the demo's profile_velocity / profile_acceleration to every
        # commanded servo if the operator asked for them. We record the
        # previous values per-servo so they can be restored on finalize
        # regardless of how the run exits (completion, safety halt,
        # operator stop, exception). When the config leaves these at
        # ``None`` the bus default is preserved — no writes happen.
        previous_profile_by_servo: dict[int, dict[str, int]] = {}
        if live_bus_lock and (
            self.config.profile_velocity is not None
            or self.config.profile_acceleration is not None
        ):
            self._push_profile_settings(
                servo_service=servo_service,
                commanded_ids=commanded_ids,
                velocity=self.config.profile_velocity,
                acceleration=self.config.profile_acceleration,
                previous_by_servo=previous_profile_by_servo,
            )

        previous_elapsed = 0.0
        try:
            for index, point in enumerate(self._trajectory):
                if session.stop_requested():
                    self._stop_reason = "operator_stop"
                    break
                command = build_two_segment_command_for_point(
                    point, bottom_segment_key=bottom_segment_key or SEGMENT_A
                )
                intended_flat = command.to_flat(context=context)
                if self.config.top_segment_tendon_routing_compensation:
                    servo_flat, _info = _apply_top_routing_compensation(intended_flat, context=context)
                else:
                    servo_flat = list(intended_flat)
                goal_ticks = mapper.to_goal_positions(servo_flat, startup_ticks)
                goals_by_servo = {int(servo_id): int(goal) for servo_id, goal in zip(commanded_ids, goal_ticks)}

                skip_reason: str | None = None
                command_sent = False
                present_ticks_by_servo: dict[int, int | None] = {int(s): None for s in commanded_ids}
                max_current_ma: int | None = None
                safety_state = "ok"

                if self._safety_halted:
                    skip_reason = "safety_halt"
                    safety_state = "halted"
                elif self.config.dry_run or servo_service is None:
                    skip_reason = "dry_run"
                    safety_state = "dry_run"
                else:
                    # Step-size guard. If max_step_ticks_per_update would be
                    # violated, we DO interpolate towards the goal via the same
                    # bus path (no special interim mode) by simply skipping the
                    # write this tick and recording the skip in the trace; the
                    # operator can review and rerun with a smaller cycle. This
                    # never writes a faster step than configured.
                    violation, observed, offender = _max_step_violation(
                        goals_by_servo=goals_by_servo,
                        previous_goals_by_servo=self._previous_goals_by_servo,
                        max_step_ticks=int(self.config.max_step_ticks_per_update),
                    )
                    if violation and self._previous_goals_by_servo:
                        skip_reason = (
                            f"step_limit: servo {offender} would step {observed} ticks > cap "
                            f"{int(self.config.max_step_ticks_per_update)}"
                        )
                        safety_state = "step_clamped"
                    else:
                        try:
                            writer = getattr(servo_service, "_write_goal_positions", None)
                            if not callable(writer):
                                raise RuntimeError("ServoService all-8 raw goal writer is unavailable.")
                            writer(goals_by_servo)
                            command_sent = True
                            self._previous_goals_by_servo = dict(goals_by_servo)
                        except Exception as exc:
                            skip_reason = f"bus_error: {exc}"
                            safety_state = "bus_error"
                    if command_sent and not self.config.dry_run:
                        try:
                            telemetry = servo_service.read_live_telemetry(commanded_ids)
                            for servo_id, item in telemetry.items():
                                if item is None:
                                    continue
                                value = getattr(item, "present_position", None)
                                if value is not None:
                                    present_ticks_by_servo[int(servo_id)] = int(value)
                            max_current_ma = _telemetry_max_current_ma(telemetry)
                            if max_current_ma is not None:
                                if self._max_current_observed_ma is None or max_current_ma > self._max_current_observed_ma:
                                    self._max_current_observed_ma = max_current_ma
                                if max_current_ma >= int(self.config.sustained_overcurrent_ma):
                                    self._consecutive_overcurrent_cycles += 1
                                else:
                                    self._consecutive_overcurrent_cycles = 0
                                if self._consecutive_overcurrent_cycles >= int(self.config.sustained_overcurrent_sample_count):
                                    self._safety_halted = True
                                    self._stop_reason = "sustained_overcurrent"
                                    safety_state = "overcurrent_halt"
                                    LOG.warning(
                                        "two_segment_slow_motion_demo: sustained overcurrent halt at sample %s",
                                        int(index),
                                    )
                        except Exception as exc:
                            skip_reason = f"telemetry_error: {exc}"
                            safety_state = "telemetry_error"

                self._trace.append(
                    DemoTraceRow(
                        sample_index=int(point.sample_index),
                        elapsed_s=float(point.elapsed_s),
                        phase_label=str(point.phase_label),
                        bottom_x_cm=float(point.bottom_x_cm),
                        bottom_y_cm=float(point.bottom_y_cm),
                        top_x_cm=float(point.top_x_cm),
                        top_y_cm=float(point.top_y_cm),
                        intended_flat_cm=list(intended_flat),
                        servo_flat_cm=list(servo_flat),
                        goal_ticks_by_servo=dict(goals_by_servo),
                        present_ticks_by_servo=dict(present_ticks_by_servo),
                        max_current_ma=max_current_ma,
                        command_sent=bool(command_sent),
                        skip_reason=skip_reason,
                        safety_state=safety_state,
                    )
                )
                session.add_sample(
                    ExperimentTimeseriesSample(
                        monotonic_time_s=float(point.elapsed_s),
                        wall_time_utc=datetime.now(timezone.utc).isoformat(),
                        phase=str(point.phase_label),
                        step_index=int(index),
                        sample_index=int(index),
                        commanded_cable_deltas_cm=list(intended_flat),
                        commanded_motor_values={str(k): int(v) for k, v in goals_by_servo.items()},
                        status_flags=["demo_only", "not_thesis_evidence"]
                        + (["dry_run"] if self.config.dry_run else [])
                        + (["safety_halt"] if self._safety_halted else []),
                        extra={
                            "record_kind": "two_segment_slow_motion_demo_point",
                            "pattern": self.config.pattern,
                            "bottom_x_cm": float(point.bottom_x_cm),
                            "bottom_y_cm": float(point.bottom_y_cm),
                            "top_x_cm": float(point.top_x_cm),
                            "top_y_cm": float(point.top_y_cm),
                            "skip_reason": skip_reason,
                            "command_sent": bool(command_sent),
                            "safety_state": safety_state,
                        },
                    )
                )
                session.update_progress(index + 1, len(self._trajectory), {"phase": point.phase_label})

                # Sleep to the next tick.
                dt = max(0.0, float(point.elapsed_s) - float(previous_elapsed))
                if dt > 0.0 and not self.config.dry_run:
                    sleep_fn(dt)
                previous_elapsed = float(point.elapsed_s)
                if self._safety_halted:
                    break
        finally:
            # Restore the per-servo profile_velocity / profile_acceleration
            # values we captured before the run so the slow motion demo
            # does not silently leave the bus configured for "lazy drift"
            # speed when the operator switches to the next experiment.
            # We do this BEFORE releasing the bus lock so the restore
            # writes go through the same exclusive ownership the rest of
            # the run used.
            if previous_profile_by_servo:
                self._restore_profile_settings(
                    servo_service=servo_service,
                    previous_by_servo=previous_profile_by_servo,
                )
            if bus_owner_cm is not None:
                try:
                    bus_owner_cm.__exit__(None, None, None)
                except Exception as exc:  # belt-and-braces; do not mask the run
                    LOG.warning(
                        "two_segment_slow_motion_demo: bus ownership release failed: %s",
                        exc,
                    )

        if self._stop_reason == "not_started":
            self._stop_reason = "completed"
        session.set_metric("captured_sample_count", len(self._trace))
        session.set_metric("max_current_observed_ma", self._max_current_observed_ma)
        session.set_metric("stop_reason", str(self._stop_reason))
        session.set_metric("safety_halted", bool(self._safety_halted))

    def _push_profile_settings(
        self,
        *,
        servo_service: Any,
        commanded_ids: list[int],
        velocity: int | None,
        acceleration: int | None,
        previous_by_servo: dict[int, dict[str, int]],
    ) -> None:
        """Push profile_velocity / profile_acceleration to every commanded servo.

        Records the previous value per-servo into ``previous_by_servo`` so
        ``_restore_profile_settings`` can put them back on finalize. Writes
        skip silently when the bus does not expose the corresponding
        write/read helpers (e.g. mock buses in tests).
        """
        bus = getattr(servo_service, "dxl_bus", None)
        if bus is None:
            return
        read_vel = getattr(bus, "read_profile_velocity", None)
        read_acc = getattr(bus, "read_profile_acceleration", None)
        write_vel = getattr(bus, "write_profile_velocity", None)
        write_acc = getattr(bus, "write_profile_acceleration", None)
        for servo_id in commanded_ids:
            sid = int(servo_id)
            previous_entry: dict[str, int] = {}
            try:
                if velocity is not None and callable(read_vel) and callable(write_vel):
                    previous_entry["velocity"] = int(read_vel(sid))
                    write_vel(sid, int(velocity))
                if acceleration is not None and callable(read_acc) and callable(write_acc):
                    previous_entry["acceleration"] = int(read_acc(sid))
                    write_acc(sid, int(acceleration))
            except Exception as exc:  # noqa: BLE001 — log + continue
                LOG.warning(
                    "two_segment_slow_motion_demo: profile push failed for servo %s: %s",
                    sid,
                    exc,
                )
                # Roll back this servo if a partial push happened.
                if "velocity" in previous_entry and callable(write_vel):
                    try:
                        write_vel(sid, int(previous_entry["velocity"]))
                    except Exception:
                        pass
                if "acceleration" in previous_entry and callable(write_acc):
                    try:
                        write_acc(sid, int(previous_entry["acceleration"]))
                    except Exception:
                        pass
                continue
            if previous_entry:
                previous_by_servo[sid] = previous_entry

    def _restore_profile_settings(
        self,
        *,
        servo_service: Any,
        previous_by_servo: dict[int, dict[str, int]],
    ) -> None:
        """Restore the profile_velocity / profile_acceleration values captured
        before the run. Records success / failure per servo onto
        ``self._profile_restore_success`` and a human-readable failure
        reason onto ``self._profile_restore_failure_reason`` so the summary
        can surface it loudly. A LOUD warning at WARNING level fires when
        any restore fails — silent failure here would leave the bus
        configured at lazy-drift speed and silently break the next
        experiment."""
        bus = getattr(servo_service, "dxl_bus", None)
        if bus is None:
            # No bus to restore against. Surface as "n/a" rather than
            # success so audit tools can distinguish bus-absence from a
            # confirmed restore.
            self._profile_restore_success = None
            self._profile_restore_failure_reason = "no_dxl_bus_attribute"
            return
        write_vel = getattr(bus, "write_profile_velocity", None)
        write_acc = getattr(bus, "write_profile_acceleration", None)
        failed_servos: list[tuple[int, str]] = []
        for sid, entry in previous_by_servo.items():
            try:
                if "velocity" in entry and callable(write_vel):
                    write_vel(int(sid), int(entry["velocity"]))
                if "acceleration" in entry and callable(write_acc):
                    write_acc(int(sid), int(entry["acceleration"]))
            except Exception as exc:  # noqa: BLE001 — log + continue
                LOG.warning(
                    "two_segment_slow_motion_demo: profile restore failed for servo %s: %s",
                    sid,
                    exc,
                )
                failed_servos.append((int(sid), str(exc)))
        if failed_servos:
            self._profile_restore_success = False
            self._profile_restore_failure_reason = (
                "; ".join(f"servo {sid}: {msg}" for sid, msg in failed_servos)
            )
            LOG.warning(
                "two_segment_slow_motion_demo: profile restore INCOMPLETE on %d servos. "
                "Bus may still be configured for demo speed. Operator action: "
                "reconnect bus and run profile_restore / neutral jog before any "
                "non-demo experiment.",
                len(failed_servos),
            )
        else:
            self._profile_restore_success = True
            self._profile_restore_failure_reason = None

    def finalize(self, session: ExperimentSession) -> None:
        if self.config.dry_run or not self.config.return_to_neutral_at_end:
            return
        servo_service = session.context.servo_service
        if servo_service is None or not servo_service.is_connected:
            return
        try:
            writer = getattr(servo_service, "_write_goal_positions", None)
            if not callable(writer):
                return
            # Best-effort return to startup neutral. We deliberately do not
            # ramp here: the trajectory's ramp_out already coasted the robot
            # to neutral; this is a safety belt-and-braces final write so
            # that if the trajectory was interrupted the bus is at neutral.
            # Acquire exclusive ownership here too: the execute() loop has
            # already released the bus (finally block) by the time finalize
            # runs, so any background poller could be holding it. Without
            # the wrap the neutral write would race the poller and could
            # fail with the same "bus already owned" error that this fix
            # addresses for the main loop.
            with servo_service.exclusive_bus_operation(
                owner="two_segment_slow_motion_demo:finalize",
                reason="return-to-neutral after slow motion demo",
            ):
                neutral_goals = {
                    int(servo_id): int(value)
                    for servo_id, value in self._startup_ticks_by_servo.items()
                }
                writer(neutral_goals)
        except Exception as exc:  # safety belt-and-braces; do not mask the run
            LOG.warning("two_segment_slow_motion_demo: return-to-neutral failed: %s", exc)

    def summarize(self, session: ExperimentSession) -> dict[str, Any]:
        metrics = dict(session.metrics)
        sent_count = sum(1 for row in self._trace if row.command_sent)
        skipped_count = sum(1 for row in self._trace if row.skip_reason is not None)
        metrics["pattern"] = self.config.pattern
        metrics["amplitude_cm"] = float(self.config.amplitude_cm)
        metrics["cycle_duration_s"] = float(self.config.cycle_duration_s)
        metrics["cycles"] = int(self.config.cycles)
        metrics["update_rate_hz"] = float(self.config.update_rate_hz)
        metrics["coupling"] = self.config.coupling
        metrics["sample_count"] = len(self._trace)
        metrics["command_sent_count"] = int(sent_count)
        metrics["command_skipped_count"] = int(skipped_count)
        metrics["max_current_observed_ma"] = self._max_current_observed_ma
        metrics["stop_reason"] = self._stop_reason
        metrics["safety_halted"] = bool(self._safety_halted)
        metrics["dry_run"] = bool(self.config.dry_run)
        metrics["valid_for_model_training"] = False
        metrics["valid_for_thesis_repeatability"] = False
        metrics["demo_only"] = True
        metrics["motion_pattern_demo"] = True
        metrics["closed_loop_control"] = False
        # Profile restore status — surface loudly so audits / next-experiment
        # gates can see whether the bus was left at demo speed.
        metrics["profile_restore_success"] = self._profile_restore_success
        metrics["profile_restore_failure_reason"] = self._profile_restore_failure_reason
        # Sci-fi relay metadata. Only present for the relay pattern; for
        # every other pattern these stay empty so existing consumers are
        # unaffected.
        if str(self.config.pattern or "").strip().lower() == "sci_fi_waypoint_relay":
            metrics["video_duration_s"] = float(self.config.video_duration_s)
            metrics["waypoint_count"] = int(self.config.waypoint_count)
            metrics["early_switch_fraction"] = float(self.config.early_switch_fraction)
            metrics["waypoint_source"] = str(self.config.waypoint_source)
            metrics["relay_seed"] = int(self.config.relay_seed)
            metrics["resolved_relay_seed"] = int(self._resolved_relay_seed)
            metrics["auto_select_seed"] = bool(self.config.auto_select_seed)
            metrics["profile_velocity"] = self.config.profile_velocity
            metrics["profile_acceleration"] = self.config.profile_acceleration
            metrics["command_rate_hz"] = float(self.config.command_rate_hz)
            if self._relay_advisory is not None:
                metrics["relay_speed_class"] = str(self._relay_advisory.speed_class)
                metrics["seconds_per_waypoint"] = float(self._relay_advisory.seconds_per_waypoint)
                metrics["estimated_bus_writes"] = int(self._relay_advisory.estimated_bus_writes)
                metrics["relay_advisory_warnings"] = list(self._relay_advisory.warnings)
        return metrics

    def write_outputs(self, session: ExperimentSession, paths, summary) -> None:
        output_dir = Path(paths.output_dir)
        output_dir.mkdir(parents=True, exist_ok=True)
        write_demo_trace_csv(output_dir / "demo_trace.csv", self._trace)
        write_demo_trace_jsonl(output_dir / "demo_trace.jsonl", self._trace)
        write_demo_summary(output_dir, summary=summary, config=self.config, trace=self._trace)
        # Sci-fi-relay-specific outputs. Only emit when the relay pattern
        # was the actual mode used so other patterns' bundles stay clean.
        if str(self.config.pattern or "").strip().lower() == "sci_fi_waypoint_relay":
            try:
                from continuum_robot.demo.sci_fi_waypoint_relay_outputs import (
                    write_sci_fi_relay_outputs,
                )
                write_sci_fi_relay_outputs(
                    output_dir=output_dir,
                    config=self.config,
                    waypoints=self._relay_waypoints,
                    schedule=self._relay_schedule,
                    resolved_seed=int(self._resolved_relay_seed),
                    advisory=self._relay_advisory,
                    profile_restore_success=self._profile_restore_success,
                    profile_restore_failure_reason=self._profile_restore_failure_reason,
                    trace=self._trace,
                )
            except Exception as exc:  # noqa: BLE001 — never block bundle on figure failure
                LOG.exception(
                    "two_segment_slow_motion_demo: sci-fi relay outputs failed: %s", exc,
                )


# ---------------------------------------------------------------------------
# Adapters for collect-pose helper reuse
# ---------------------------------------------------------------------------


class _StartupResolveAdapter:
    """Adapter so we can call ``_resolve_startup_ticks`` without importing
    the full collect-pose config. The helper only reads ``dry_run`` and the
    trust-mode flags; everything else is ignored."""

    def __init__(self, config: TwoSegmentSlowMotionDemoConfig) -> None:
        self.dry_run = bool(config.dry_run)
        self.allow_servo_only_test_run = bool(config.allow_servo_only_test_run)
        self.run_trust_mode = "servo_only" if config.allow_servo_only_test_run else "thesis_trusted"


class _DryRunMapper:
    """Mapper stub used when no servo service is connected.

    Implements the same ``to_goal_positions`` contract used by the real
    ``TendonDisplacementMapper`` but assumes a 2 cm spool / 4096 ticks/rev.
    The demo trace can still be inspected end-to-end without instantiating
    hardware.
    """

    spool_diameter_cm = 2.0
    ticks_per_rev = 4096

    def displacement_cm_to_ticks(self, displacement_cm: float) -> int:
        circumference = math.pi * float(self.spool_diameter_cm)
        rev = float(displacement_cm) / circumference
        return int(round(rev * float(self.ticks_per_rev)))

    def to_goal_positions(self, tendon_displacements_cm: list[float], neutral_ticks: list[int]) -> list[int]:
        return [
            int(neutral) + int(self.displacement_cm_to_ticks(float(dl)))
            for dl, neutral in zip(tendon_displacements_cm, neutral_ticks)
        ]


class _DryRunContext:
    """Minimal stand-in for ``RobotOperatingContext`` used in dry-run smoke
    tests. The flat-command serializer in ``TwoSegmentCommand.to_flat``
    needs ``commanded_servo_ids`` (8 ids) + a ``metadata()`` payload with
    per-segment ``servo_ids`` lists; we default to segment_a = [1..4] and
    segment_b = [5..8] with bottom on segment_a.
    """

    operating_mode = "dual_segment"
    expected_servo_ids = [1, 2, 3, 4, 5, 6, 7, 8]
    commanded_servo_ids = [1, 2, 3, 4, 5, 6, 7, 8]
    bottom_segment_key = SEGMENT_A
    top_segment_key = SEGMENT_B
    bottom_servo_ids = [1, 2, 3, 4]
    top_servo_ids = [5, 6, 7, 8]
    physical_assembly_issues: list[str] = []

    def metadata(self) -> dict[str, Any]:
        return {
            "segments": {
                SEGMENT_A: {
                    "key": SEGMENT_A,
                    "label": "Segment A",
                    "segment_role": "bottom",
                    "servo_ids": [1, 2, 3, 4],
                },
                SEGMENT_B: {
                    "key": SEGMENT_B,
                    "label": "Segment B",
                    "segment_role": "top",
                    "servo_ids": [5, 6, 7, 8],
                },
            },
            "physical_assembly": {
                "bottom_segment_key": SEGMENT_A,
                "top_segment_key": SEGMENT_B,
                "bottom_segment_label": "Segment A",
                "top_segment_label": "Segment B",
                "bottom_servo_ids": [1, 2, 3, 4],
                "top_servo_ids": [5, 6, 7, 8],
                "lower_tick_means_tension": True,
            },
        }


# ---------------------------------------------------------------------------
# Output writers
# ---------------------------------------------------------------------------


DEMO_TRACE_CSV_COLUMNS = (
    "sample_index",
    "elapsed_s",
    "phase_label",
    "bottom_x_cm",
    "bottom_y_cm",
    "top_x_cm",
    "top_y_cm",
    "intended_flat_cm",
    "servo_flat_cm",
    "goal_ticks_by_servo",
    "present_ticks_by_servo",
    "max_current_ma",
    "command_sent",
    "skip_reason",
    "safety_state",
)


def write_demo_trace_csv(path: Path, trace: list[DemoTraceRow]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow(DEMO_TRACE_CSV_COLUMNS)
        for row in trace:
            data = row.to_dict()
            writer.writerow(
                [
                    int(data["sample_index"]),
                    f"{float(data['elapsed_s']):.6f}",
                    str(data["phase_label"]),
                    f"{float(data['bottom_x_cm']):.6f}",
                    f"{float(data['bottom_y_cm']):.6f}",
                    f"{float(data['top_x_cm']):.6f}",
                    f"{float(data['top_y_cm']):.6f}",
                    json.dumps(data["intended_flat_cm"]),
                    json.dumps(data["servo_flat_cm"]),
                    json.dumps(data["goal_ticks_by_servo"]),
                    json.dumps(data["present_ticks_by_servo"]),
                    "" if data["max_current_ma"] is None else int(data["max_current_ma"]),
                    "1" if data["command_sent"] else "0",
                    "" if data["skip_reason"] is None else str(data["skip_reason"]),
                    str(data["safety_state"]),
                ]
            )


def write_demo_trace_jsonl(path: Path, trace: list[DemoTraceRow]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as handle:
        for row in trace:
            handle.write(json.dumps(row.to_dict(), sort_keys=True))
            handle.write("\n")


def write_demo_summary(
    output_dir: Path,
    *,
    summary: Any,
    config: TwoSegmentSlowMotionDemoConfig,
    trace: list[DemoTraceRow],
) -> None:
    metrics = {}
    if hasattr(summary, "to_dict"):
        try:
            metrics = dict(summary.to_dict())
        except Exception:
            metrics = {}
    elif isinstance(summary, dict):
        metrics = dict(summary)
    metrics.setdefault("demo_only", True)
    metrics.setdefault("valid_for_model_training", False)
    metrics.setdefault("valid_for_thesis_repeatability", False)
    metrics.setdefault("motion_pattern_demo", True)
    metrics.setdefault("closed_loop_control", False)
    # Write the demo-flavoured summary to a SEPARATE filename so we do not
    # clobber the canonical ``summary.json`` written by ExperimentDatasetWriter.
    # The canonical file follows the ExperimentSummary dataclass schema
    # (schema_version / experiment_name / sample_counts / ...); rewriting it
    # with a flat metric dict made ExperimentSummary.from_dict() fail later
    # with "got an unexpected keyword argument 'closed_loop_control'" the
    # next time the GUI/CLI tried to reload the run.
    (output_dir / "demo_summary.json").write_text(
        json.dumps(metrics, indent=2, sort_keys=True, default=str), encoding="utf-8"
    )
    lines = [
        "Two-Segment Slow Motion Demo Summary",
        "=" * 36,
        f"Pattern:            {config.pattern}",
        f"Amplitude (cm):     {config.amplitude_cm}",
        f"Cycle duration (s): {config.cycle_duration_s}",
        f"Cycles:             {config.cycles}",
        f"Coupling:           {config.coupling}",
        f"Update rate (Hz):   {config.update_rate_hz}",
        f"Sample count:       {len(trace)}",
        f"Dry-run:            {bool(config.dry_run)}",
        "",
        "Validity:",
        "  demo_only: True",
        "  valid_for_model_training: False",
        "  valid_for_thesis_repeatability: False",
        "  closed_loop_control: False",
        "",
        "This is a presentation-only motion pattern demo. It is not data and is not",
        "suitable for model training or thesis repeatability claims.",
        "",
    ]
    (output_dir / "two_segment_slow_motion_demo_summary.txt").write_text(
        "\n".join(lines), encoding="utf-8"
    )


# ---------------------------------------------------------------------------
# Registry
# ---------------------------------------------------------------------------


def register_two_segment_slow_motion_demo(registry) -> None:
    """Register the slow motion demo with the experiment registry."""
    registry.register(
        name=TwoSegmentSlowMotionDemoExperiment.name,
        title="Two-Segment Slow Motion Demo",
        description=TwoSegmentSlowMotionDemoExperiment.description,
        category="demo",
        tags=["Demo", "TwoSegment", "MotionPattern", "Presentation"],
        default_config_path="config/experiment_two_segment_slow_motion_demo.example.yaml",
        factory=TwoSegmentSlowMotionDemoExperiment.from_dict,
    )
